#!/usr/bin/env python3

import rclpy
from rclpy.node import Node


class PlaybackService(Node):
    """Compatibility node.

    HTTP playback APIs now live in robot_setting/robot_mode_service.py.
    Playback commands and status use ROS topics:
    - control/playback_control
    - /playback_status
    """

    def __init__(self):
        super().__init__('playback_service')
        self.get_logger().warning(
            'playback_service no longer starts an HTTP server. '
            'Use robot_setting on port 8001 for playback HTTP APIs.'
        )


def main(args=None):
    rclpy.init(args=args)
    node = PlaybackService()

    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
